def validate_items(items):
    # Check for empty items and invalid prices/quantities
    if not items:
        raise ValueError("Items list cannot be empty")
    for item in items:
        if 'price' not in item or 'quantity' not in item or item['price'] <= 0 or item['quantity'] < 0:
            raise ValueError(f"Invalid item: {item}")

def calculate_totals(items, customer_type):
    # Calculate subtotal, tax, and total based on items and customer type
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    tax_rate = {'regular': 0.08, 'premium': 0.12}[customer_type]
    tax = subtotal * tax_rate
    total = subtotal + tax
    return {'subtotal': subtotal, 'tax': tax, 'total': total}

def format_receipt(items, totals):
    # Format receipt string with item quantities and the total
    receipt = "Receipt\n"
    for item in items:
        receipt += f"{item['name']}: {item['quantity']} x ${item['price']:.2f} = ${item['price'] * item['quantity']:.2f}\n"
    receipt += f"\nSubtotal: ${totals['subtotal']:.2f}, Tax (${tax_rate * 100}%): ${totals['tax']:.2f}, Total: ${totals['total']:.2f}"
    return receipt

def process_order(items, customer_type):
    validate_items(items)
    totals = calculate_totals(items, customer_type)
    receipt = format_receipt(items, totals)
    return {'total': totals['total'], 'receipt': receipt}
